class Order {
  constructor(id, effort) {
    this.id = id;
    this.effort = effort;
  }
}

class Worker {
  constructor(name, energy) {
    this.name = name;
    this.energy = energy;
    this.itemsCompleted = 0;
  }

  completeOrder(order) {
    this.energy = Math.max(0, this.energy - order.effort);
    this.itemsCompleted += 1;
  }

  isExhausted() {
    return this.energy <= 0;
  }
}

function runProduction(worker, orders) {
  while (orders.length > 0 && !worker.isExhausted()) {
    const next = orders[0];
    if (worker.energy < next.effort) {
      console.log(`${worker.name} collapsed before completing Order ${next.id}.`);
      worker.energy = 0;
      break;
    }
    orders.shift();
    worker.completeOrder(next);
    console.log(`Order ${next.id} completed. Energy remaining: ${worker.energy}.`);
  }
  if (orders.length === 0) {
    console.log(`All orders completed! ${worker.name} finished ${worker.itemsCompleted} orders.`);
  } else {
    console.log(`${worker.name} collapsed with ${orders.length} order(s) still waiting.`);
  }
}

const bo = new Worker("Bo", 20);
const queue = [new Order(1, 5), new Order(2, 5), new Order(3, 5)];
runProduction(bo, queue);

